/// Unit tests of this module's tables. Every entry in [`STATES`] and
/// [`MOBJINFO`] is keyed by integer index, so any drift in the `SPR_*`,
/// `MT_*`, or `MF_*` numbering silently retargets every cross-table
/// reference.
#[cfg(test)]
mod tests {
    use {super::*, crate::engine::doom::player::PspdefT};

    /// The all-zero table indices of zeroed map objects and players are
    /// `S_NULL` (C's null state) and `MT_PLAYER`, and the indices name the
    /// table entries they were made from.
    #[test]
    fn table_indices_name_their_entries() {
        let zeroed_psprite: PspdefT = unsafe { std::mem::zeroed() };
        assert!(zeroed_psprite.state.is_null());
        assert_eq!(StateNum::default(), StateNum::NULL);
        assert_eq!(StateNum::NULL.number(), S_NULL);
        assert_eq!(MobjType::default().number(), MT_PLAYER);

        let last_state = StateNum::new(NUMSTATES as i32 - 1);
        assert_eq!(last_state.number(), S_TECH2LAMP4);
        assert_eq!(StateNum::new(S_PLAY_RUN4).get().nextstate, S_PLAY_RUN1);
        assert_eq!(
            MobjType::new(MT_TROOP).get().spawnstate,
            MOBJINFO.borrow()[MT_TROOP as usize].spawnstate
        );
        assert_eq!(
            MobjType::new(NUMMOBJTYPES as i32 - 1).number(),
            NUMMOBJTYPES as i32 - 1
        );
    }

    #[test]
    #[should_panic(expected = "is not in the state table")]
    fn state_index_past_the_table_panics() {
        StateNum::new(NUMSTATES as i32);
    }

    #[test]
    #[should_panic(expected = "is not in the thing table")]
    fn thing_type_past_the_table_panics() {
        MobjType::new(-1);
    }

    /// Verify that the mobjinfo table is internally consistent:
    /// the spawnstate of each well-known mobj type should point to a state
    /// whose sprite matches the expected SPR_* constant.  This catches
    /// index-vs-table drift (e.g. MT_PUFF pointing at S_BLOOD1 because
    /// the MT enum or states table was edited incorrectly).
    #[test]
    fn mobjinfo_spawnstate_sprite_cross_reference() {
        {
            let mobjinfo = MOBJINFO.borrow();
            let states = STATES.borrow();
            let cases: [(i32, i32, i32, &str); 7] = [
                (MT_PUFF, S_PUFF1, SPR_PUFF, "MT_PUFF → S_PUFF1 → SPR_PUFF"),
                (
                    MT_BLOOD,
                    S_BLOOD1,
                    SPR_BLUD,
                    "MT_BLOOD → S_BLOOD1 → SPR_BLUD",
                ),
                (MT_TFOG, S_TFOG, SPR_TFOG, "MT_TFOG → S_TFOG → SPR_TFOG"),
                (MT_IFOG, S_IFOG, SPR_IFOG, "MT_IFOG → S_IFOG → SPR_IFOG"),
                (MT_PLAYER, S_PLAY, SPR_PLAY, "MT_PLAYER → S_PLAY → SPR_PLAY"),
                (
                    MT_ROCKET,
                    S_ROCKET,
                    SPR_MISL,
                    "MT_ROCKET → S_ROCKET → SPR_MISL",
                ),
                (
                    MT_PLASMA,
                    S_PLASBALL,
                    SPR_PLSS,
                    "MT_PLASMA → S_PLASBALL → SPR_PLSS",
                ),
            ];
            for (mt, expected_state, expected_sprite, desc) in cases {
                let info = &mobjinfo[mt as usize];
                assert_eq!(
                    info.spawnstate, expected_state,
                    "{}: spawnstate mismatch",
                    desc
                );
                let st = &states[info.spawnstate as usize];
                assert_eq!(st.sprite, expected_sprite, "{}: sprite mismatch", desc);
            }
        }
    }

    /// Verify that the mobjinfo table entries for items have the expected
    /// MF_SPECIAL flag.  MT_INV and MT_INS have MF_SPECIAL (they are
    /// pick-up items) but are explicitly excluded from the respawn queue
    /// in P_RemoveMobj.
    #[test]
    fn mobjinfo_respawn_flags_consistent() {
        {
            let mobjinfo = MOBJINFO.borrow();
            // Power-ups have MF_SPECIAL despite being excluded from respawn
            assert!(
                mobjinfo[MT_INV as usize].flags & MF_SPECIAL != 0,
                "MT_INV should have MF_SPECIAL"
            );
            assert!(
                mobjinfo[MT_INS as usize].flags & MF_SPECIAL != 0,
                "MT_INS should have MF_SPECIAL"
            );

            // A few representative items that should also have it
            assert!(
                mobjinfo[MT_CLIP as usize].flags & MF_SPECIAL != 0,
                "MT_CLIP should have MF_SPECIAL"
            );
            assert!(
                mobjinfo[MT_MISC10 as usize].flags & MF_SPECIAL != 0,
                "MT_MISC10 (stimpack) should have MF_SPECIAL"
            );
            assert!(
                mobjinfo[MT_MISC11 as usize].flags & MF_SPECIAL != 0,
                "MT_MISC11 (medikit) should have MF_SPECIAL"
            );
        }
    }

    /// Every state `P_SetPsprite` can enter (the weapon states reachable
    /// from `weaponinfo`, including `A_FireCGun`'s second flash frame) has a
    /// `Weapon` action or none, and every other state, entered only through
    /// `P_SetMobjState`, has a `Mobj` action or none.
    #[test]
    fn state_actions_match_their_caller() {
        use crate::engine::doom::items::weaponinfo;

        let mut weapon_state = [false; NUMSTATES];
        let mut pending: Vec<i32> = weaponinfo
            .iter()
            .flat_map(|weapon| {
                [
                    weapon.upstate,
                    weapon.downstate,
                    weapon.readystate,
                    weapon.atkstate,
                    weapon.flashstate,
                    weapon.flashstate + 1,
                ]
            })
            .collect();
        while let Some(state) = pending.pop() {
            if state == S_NULL || weapon_state[state as usize] {
                continue;
            }
            weapon_state[state as usize] = true;
            pending.push(STATES.borrow()[state as usize].nextstate);
        }

        let mut mobj_actions = 0;
        let mut weapon_actions = 0;
        for (index, is_weapon_state) in weapon_state.iter().enumerate() {
            let action = STATES.borrow()[index].action;
            match action {
                StateAction::None => {}
                StateAction::Mobj(_) => {
                    mobj_actions += 1;
                    assert!(!is_weapon_state, "weapon state {index} has a Mobj action");
                }
                StateAction::Weapon(_) => {
                    weapon_actions += 1;
                    assert!(
                        is_weapon_state,
                        "map-object state {index} has a Weapon action"
                    );
                }
            }
        }
        assert!(mobj_actions > 0 && weapon_actions > 0);
    }
}
